"""Single WordPress transport: isolated API doubles, no external site or publication."""
import json,subprocess,shutil,unittest,sqlite3
import test_http_security as fixtures
class WordPressWorkspace(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.fixture=type('WordPressFixture',(fixtures.HttpSecurity,),{});cls.fixture.setUpClass()
    @classmethod
    def tearDownClass(cls):cls.fixture.tearDownClass()
    def setUp(self):
        self.case=self.fixture();self.case.setUp()
        for d in ['wordpress-api','ai-private']:shutil.rmtree(self.case.app/'panel/db'/d,ignore_errors=True)
    def php(self,source):
        prefix="require $argv[1];require dirname($argv[1]).'/WordPressWorkspace.php';SessionIdentity::beginGlobal('fixture_owner');SessionIdentity::select(getCurrentProject('p',true));$p=getCurrentProject('p',true);$p['settings']['platform_type']='wordpress';$p['settings']['wordpress']=['site_url'=>'https://shop.example','token'=>str_repeat('a',64),'enabled'=>true,'auto_publish'=>true];ProjectOnboarding::mutate('p',function(&$x)use($p){$x['settings']=$p['settings'];});"
        proc=subprocess.run([fixtures.PHP,'-r',prefix+source,str(self.case.app/'panel/inc/functions.php')],capture_output=True,text=True)
        self.assertEqual(proc.returncode,0,proc.stderr);return json.loads(proc.stdout)
    def test_independent_token_is_stable_and_does_not_enable_or_convert_project(self):
        r=self.php("ProjectOnboarding::mutate('p',function(&$x){$x['settings']['platform_type']='custom';unset($x['settings']['wordpress']);});$svc=new WordPressWorkspace();$first=$svc->ensureToken(getCurrentProject('p',true));$second=$svc->ensureToken(getCurrentProject('p',true));$saved=getCurrentProject('p',true);echo json_encode(['first'=>$first,'second'=>$second,'settings'=>$saved['settings']]);")
        self.assertEqual(len(r['first']),64);self.assertEqual(r['first'],r['second']);self.assertEqual(r['settings']['platform_type'],'custom');self.assertEqual(r['settings']['wordpress'],{'token':r['first']})

    def test_plugin_download_contains_complete_installable_assets(self):
        import io,zipfile
        owner,_=self.case.login()
        # Read the actual download bytes rather than the fixture's text helper.
        with owner.open(self.case.base+'/panel/wp-crm.php?project=p&download_plugin=1') as response:
            self.assertEqual(response.headers.get_content_type(),'application/zip');data=response.read()
        with zipfile.ZipFile(io.BytesIO(data)) as package:
            self.assertIsNone(package.testzip())
            for name in ['maarksho-crm-sync.php','settings-view.php','assets/admin.css','assets/admin.js']:
                self.assertEqual(package.read('maarksho-crm-sync/'+name),(self.case.app/'integrations/wordpress/maarksho-crm-sync'/name).read_bytes())

    def test_view_only_connection_cannot_reveal_or_generate_token(self):
        self.php("ProjectOnboarding::mutate('p',function(&$x){$x['settings']['active_modules'][]='wp_crm';});echo json_encode((new WordPressWorkspace())->ensureToken($p));")
        policy=self.case.app/'panel/db/access_policy.json'
        policy.write_text(json.dumps({'wp_crm':{'view':{'users':['limited']},'use':{'users':[],'roles':[]}}}))
        user,csrf=self.case.login('limited')
        code,page=self.case.request(user,'/panel/wp-crm.php?project=p');self.assertEqual(code,200);self.assertNotIn('a'*64,page);self.assertNotIn('id="wp-api-token"',page)
        code,_=self.case.request(user,'/panel/wp-crm.php?project=p',{'app_csrf':csrf,'_project_context':'p','action':'generate_token'});self.assertEqual(code,403)

    def test_wordpress_removes_crawl_step_and_rejects_new_crawl_jobs(self):
        r=self.php("$blocked=false;try{ProjectOnboarding::queue($p);}catch(RuntimeException $e){$blocked=true;}echo json_encode(['steps'=>array_keys(ProjectOnboarding::steps($p)),'blocked'=>$blocked]);")
        self.assertNotIn('crawl',r['steps']);self.assertTrue(r['blocked'])
    def test_test_uses_get_and_rejects_old_plugin(self):
        r=self.php("$methods=[];$svc=new WordPressWorkspace(null,function($url,$body,$headers)use(&$methods){$methods[]=[$url,$body,$headers];return ['status'=>200,'body'=>['status'=>'success','version'=>'5.0.0']];});$blocked=false;try{$svc->test($p);}catch(RuntimeException $e){$blocked=true;}echo json_encode([$blocked,$methods]);")
        self.assertTrue(r[0]);self.assertIsNone(r[1][0][1]);self.assertTrue(r[1][0][0].endswith('/test'))
    def test_products_enter_library_by_exact_wordpress_id_and_preserve_manual_images(self):
        r=self.php("$rows=[['id'=>'101','name'=>'WP model','sku'=>'WP-101','url'=>'https://shop.example/product/101','status'=>'publish','stock'=>5,'price'=>10,'description'=>'Description','content_html'=>'<p>Description</p>','images'=>['https://shop.example/a.webp'],'modified_at'=>'2026-10-01T10:00:00+00:00']];$svc=new WordPressWorkspace(null,function($url,$body)use(&$rows){return ['status'=>200,'body'=>['status'=>'success','kind'=>'products','page'=>1,'next_page'=>null,'rows'=>$rows]];});$svc->pull($p,'products');$p=getCurrentProject('p',true);$local=null;foreach($p['products'] as $x)if(($x['website_sync']['wordpress']['id']??'')==='101')$local=$x;$local['image']='https://panel.example/new.webp';$local['images_list']=[['url'=>$local['image'],'source'=>'manual','approved'=>false]];$local['status']='pending';$local['has_new_manual_image']=1;db_save_project($p,[$local]);$rows[0]['stock']=7;$svc->pull(getCurrentProject('p',true),'products');$p=getCurrentProject('p',true);foreach($p['products'] as $x)if($x['id']===$local['id'])$local=$x;echo json_encode(['count'=>count($p['products']),'image'=>$local['image'],'status'=>$local['status'],'stock'=>$local['stock_total'],'remote'=>$local['website_sync']['wordpress']['id'],'fingerprint_stable'=>WordPressWorkspace::fingerprint(['price'=>10])===WordPressWorkspace::fingerprint(['price'=>'10.000'])]);")
        self.assertEqual(r['count'],6);self.assertEqual(r['image'],'https://panel.example/new.webp');self.assertEqual(r['status'],'pending');self.assertEqual(float(r['stock']),7);self.assertTrue(r['fingerprint_stable'])
    def test_approved_image_queues_idempotently_and_only_acknowledgement_marks_uploaded(self):
        r=self.php("$svc=new WordPressWorkspace(null,function($url,$body){if(strpos($url,'export?')!==false)return ['status'=>200,'body'=>['status'=>'success','kind'=>'products','page'=>1,'next_page'=>null,'rows'=>[['id'=>'101','name'=>'WP model','sku'=>'WP-101','status'=>'publish','stock'=>5,'description'=>'old','images'=>['https://shop.example/a.webp'],'modified_at'=>'v1']]]];return ['status'=>200,'body'=>['status'=>'success','modified_at'=>'v2','image_urls'=>['https://shop.example/new.webp']]];});$svc->pull($p,'products');$p=getCurrentProject('p',true);foreach($p['products'] as $x)if(($x['website_sync']['wordpress']['id']??'')==='101')$local=$x;$local['image']='https://panel.example/new.webp';$local['gallery']=[];$local['images_list']=[['url'=>$local['image'],'source'=>'manual','approved'=>false]];$local['status']='pending';$local['has_new_manual_image']=1;$blocked=false;try{$svc->queueProduct($p,$local);}catch(RuntimeException $e){$blocked=true;}$local['status']='active';$local['images_list'][0]['approved']=true;db_save_project($p,[$local]);$a=$svc->queueProduct($p,$local);$b=$svc->queueProduct($p,$local);$before=$svc->state('p');$svc->publishOne(getCurrentProject('p',true));$fresh=getCurrentProject('p',true);foreach($fresh['products'] as $x)if($x['id']===$local['id'])$local=$x;echo json_encode(['blocked'=>$blocked,'same'=>$a===$b,'count'=>count($before['jobs']),'state'=>$svc->state('p')['jobs'][$a]['state'],'image'=>$local['image'],'uploaded'=>$local['uploaded_to_site'],'stable_after_ack'=>WordPressWorkspace::fingerprint($local)===$local['website_sync']['wordpress']['published_fingerprint'],'request'=>$before['jobs'][$a]['payload']]);")
        self.assertTrue(r['blocked']);self.assertTrue(r['same']);self.assertEqual(r['count'],1);self.assertEqual(r['state'],'done');self.assertEqual(r['image'],'https://panel.example/new.webp');self.assertEqual(r['uploaded'],1);self.assertNotIn('description',r['request']);self.assertTrue(r['stable_after_ack'])
    def test_conflict_is_visible_and_does_not_fake_a_success(self):
        r=self.php("$svc=new WordPressWorkspace(null,function($url,$body){if(strpos($url,'export?')!==false)return ['status'=>200,'body'=>['status'=>'success','kind'=>'posts','page'=>1,'next_page'=>null,'rows'=>[['id'=>'50','title'=>'Old','description'=>'old','modified_at'=>'v1']]]];return ['status'=>409,'body'=>['message'=>'Content changed']];});$svc->pull($p,'posts');$id=$svc->queueContent($p,'posts','50',['title'=>'New','description'=>'New body']);$blocked=false;try{$svc->publishOne($p);}catch(RuntimeException $e){$blocked=true;}echo json_encode(['blocked'=>$blocked,'job'=>$svc->state('p')['jobs'][$id]]);")
        self.assertTrue(r['blocked']);self.assertEqual(r['job']['state'],'error');self.assertIn('409',r['job']['error'])
    def test_stale_content_and_unknown_dates_are_distinct_without_fabricated_analytics(self):
        r=self.php("$svc=new WordPressWorkspace(null,function($url,$body){return ['status'=>200,'body'=>['status'=>'success','kind'=>'posts','page'=>1,'next_page'=>null,'rows'=>[['id'=>'50','title'=>'Old','url'=>'https://shop.example/post','modified_at'=>'2020-01-01T00:00:00Z'],['id'=>'51','title'=>'Unknown','modified_at'=>null]]]];});$svc->pull($p,'posts');echo json_encode($svc->opportunities($p));")
        self.assertEqual(len(r),2);self.assertIn('بیش از ۳۰ روز',r[0]['issues'][0]);self.assertEqual(r[1]['issues'][0],'تاریخ ویرایش نامشخص');self.assertEqual(r[0]['metrics'],[])
    def test_pagination_checkpoints_and_preview_versions_do_not_silently_advance(self):
        r=self.php("$svc=new WordPressWorkspace(null,function($url,$body){parse_str(parse_url($url,PHP_URL_QUERY),$q);$page=(int)$q['page'];return ['status'=>200,'body'=>['status'=>'success','kind'=>'posts','page'=>$page,'next_page'=>$page===1?2:null,'rows'=>[['id'=>(string)(50+$page),'title'=>'Article','version'=>'v'.$page]]]];});$svc->pull($p,'posts');$first=$svc->state('p');$svc->pull($p,'posts');$last=$svc->state('p');$blocked=false;try{$svc->queueContent($p,'posts','51',['title'=>'New','description'=>'Body','expected_version'=>'wrong']);}catch(RuntimeException $e){$blocked=true;}echo json_encode(['next'=>$first['next_page']['posts'],'first_complete'=>isset($first['last_complete']['posts']),'complete'=>isset($last['last_complete']['posts']),'count'=>count($last['index']['posts']),'blocked'=>$blocked]);")
        self.assertEqual(r,{'next':2,'first_complete':False,'complete':True,'count':2,'blocked':True})
    def test_google_data_joins_by_url_and_native_plan_is_available_to_ai_reports(self):
        r=self.php("$svc=new WordPressWorkspace(null,function($url,$body){return ['status'=>200,'body'=>['status'=>'success','kind'=>'posts','page'=>1,'next_page'=>null,'rows'=>[['id'=>'50','title'=>'Article','url'=>'https://shop.example/article/','modified_at'=>'2020-01-01T00:00:00Z']]]];});$svc->pull($p,'posts');$store=new AiStore();$hub=new AiHub($store);$principal=AiAccess::principal($p);$g=$hub->createSource($p,$principal,['name'=>'GSC','origin'=>'Google','store_id'=>'p','transport'=>'google','kinds'=>['gsc']]);$a=$hub->createSource($p,$principal,['name'=>'GA4','origin'=>'Google','store_id'=>'p','transport'=>'google','kinds'=>['ga4']]);$hub->ingest($p,$hub->source($p,$g['id']),'gsc',[['id'=>'search1','date'=>date('Y-m-d',strtotime('-2 days')),'page'=>'https://shop.example/article','clicks'=>1,'impressions'=>200,'ctr'=>0.005,'position'=>8]],'gsc-fixture-1',true);$hub->ingest($p,$hub->source($p,$a['id']),'ga4',[['id'=>'ga1','date'=>date('Y-m-d',strtotime('-2 days')),'page'=>'https://shop.example/article','sessions'=>12]],'ga4-fixture-1',true);$items=$svc->opportunities($p,$g['id'],$a['id']);$svc->savePlan($p,$items,['gsc'=>$g['id'],'ga4'=>$a['id']]);$reports=(new AiContent($store))->reports($p);echo json_encode(['items'=>$items,'reports'=>$reports]);")
        self.assertEqual(r['items'][0]['metrics'],{'clicks':1,'impressions':200,'sessions':12});self.assertTrue(any('۲٪' in x for x in r['items'][0]['issues']));self.assertEqual(r['reports'][0]['origin'],'wordpress_rules')
    def test_woocommerce_unmanaged_stock_is_available_without_fabricating_quantity(self):
        r=self.php("$p=['status'=>'active','stock_total'=>'','website_sync'=>['wordpress'=>['origin'=>'https://shop.example','stock_status'=>'instock']]];echo json_encode([WebsiteCatalogSync::inventory($p),WebsiteCatalogSync::totalStock($p)]);")
        self.assertEqual(r,['in_stock',None])

    def test_acknowledged_record_replaces_stale_editor_snapshot(self):
        r=self.php("$svc=new WordPressWorkspace(null,function($url,$body){if(strpos($url,'export?')!==false)return ['status'=>200,'body'=>['status'=>'success','kind'=>'posts','page'=>1,'next_page'=>null,'rows'=>[['id'=>'50','title'=>'Old','version'=>'v1','modified_at'=>'v1']]]];return ['status'=>200,'body'=>['status'=>'success','modified_at'=>'v2','record'=>['id'=>'50','title'=>'New','content_html'=>'Updated','version'=>'v2','modified_at'=>'v2']]];});$svc->pull($p,'posts');$svc->queueContent($p,'posts','50',['title'=>'New','description'=>'Updated','expected_version'=>'v1']);$svc->publishOne($p);$row=$svc->record($p,'posts','50');$blocked=false;try{$svc->queueContent($p,'posts','50',['title'=>'Old','description'=>'Old','expected_version'=>'v1']);}catch(RuntimeException $e){$blocked=true;}echo json_encode([$row['title'],$row['version'],$blocked]);")
        self.assertEqual(r,['New','v2',True])
    def test_local_price_edits_survive_pull_and_concurrent_price_conflicts_require_confirmation(self):
        r=self.php("$rows=[['id'=>'101','name'=>'Model','sku'=>'SKU','status'=>'publish','stock'=>5,'price'=>10,'description'=>'Body','images'=>['https://shop.example/a.webp'],'version'=>'v1']];$svc=new WordPressWorkspace(null,function($url,$body)use(&$rows){return ['status'=>200,'body'=>['status'=>'success','kind'=>'products','page'=>1,'next_page'=>null,'rows'=>$rows]];});$svc->pull($p,'products');$p=getCurrentProject('p',true);foreach($p['products'] as $x)if(($x['website_sync']['wordpress']['id']??'')==='101')$local=$x;$local['price']='12';db_save_project($p,[$local]);$svc->pull(getCurrentProject('p',true),'products');$p=getCurrentProject('p',true);foreach($p['products'] as $x)if($x['id']===$local['id'])$local=$x;$preserved=$local['price'];$rows[0]['price']=15;$rows[0]['version']='v2';$svc->pull($p,'products');$p=getCurrentProject('p',true);foreach($p['products'] as $x)if($x['id']===$local['id'])$local=$x;$blocked=false;try{$svc->queueProduct($p,$local);}catch(RuntimeException $e){$blocked=true;}$job=$svc->queueProduct($p,$local,true);echo json_encode(['price'=>$preserved,'blocked'=>$blocked,'fields'=>$local['website_sync']['wordpress']['conflicts'],'payload'=>$svc->state('p')['jobs'][$job]['payload']]);")
        self.assertEqual(float(r['price']),12);self.assertTrue(r['blocked']);self.assertIn('price',r['fields']);self.assertEqual(float(r['payload']['price']),12)

    def test_missing_from_completed_snapshot_preserves_images_but_stops_publication(self):
        r=self.php("$rows=[['id'=>'101','name'=>'Model','sku'=>'SKU','status'=>'publish','stock'=>5,'price'=>10,'description'=>'Body','images'=>['https://shop.example/a.webp'],'version'=>'v1']];$svc=new WordPressWorkspace(null,function($url,$body)use(&$rows){return ['status'=>200,'body'=>['status'=>'success','kind'=>'products','page'=>1,'next_page'=>null,'rows'=>$rows]];});$svc->pull($p,'products');$rows=[];$svc->pull(getCurrentProject('p',true),'products');$p=getCurrentProject('p',true);foreach($p['products'] as $x)if(($x['website_sync']['wordpress']['id']??'')==='101')$local=$x;$blocked=false;try{$svc->queueProduct($p,$local);}catch(RuntimeException $e){$blocked=true;}echo json_encode(['inventory'=>WebsiteCatalogSync::inventory($local),'image'=>$local['image'],'blocked'=>$blocked,'stock'=>$local['stock_total'],'flag'=>$svc->rows($p,'products')[0]['_not_in_latest_snapshot']]);")
        self.assertEqual(r['inventory'],'unknown');self.assertEqual(r['image'],'https://shop.example/a.webp');self.assertTrue(r['blocked']);self.assertTrue(r['flag']);self.assertEqual(r['stock'],'')

    def test_connection_page_requires_project_grants_and_readonly_cannot_save(self):
        viewer,_=self.case.login('viewer');self.assertEqual(self.case.request(viewer,'/panel/wp-crm.php?project=p')[0],403)
        owner,csrf=self.case.login();self.assertEqual(self.case.request(owner,'/panel/wp-crm.php?project=foreign')[0],403)
        code,page=self.case.request(owner,'/wp-crm.php?project=p');self.assertEqual(code,200);self.assertIn('یک افزونه، یک اتصال',page)
        self.assertEqual(self.case.request(owner,'/panel/wp-crm.php?project=p',{'action':'save'})[0],403)
